def ref(sid, text='Source'):
    s = next(s for s in SOURCES if s[0] == sid)
    return f'<a class="source-link" href="{escape(s[3],quote=True)}" target="_blank" rel="noopener noreferrer">{escape(text)} <span aria-hidden="true">↗</span></a>'

bars = ''.join(f'<li><div class="bar-label"><span>{escape(n)}<small>{escape(note)}</small></span><strong>${v}B</strong></div><div class="bar-track" aria-hidden="true"><span style="--bar:{v/57*100:.6f}%"></span></div></li>' for n,v,note in PROGRAMS)
source_list = ''.join(f'<li id="source-{s[0]}"><span class="source-num">{i:02}</span><div>{ref(s[0],s[1])}<p>{escape(s[2])}</p></div></li>' for i,s in enumerate(SOURCES,1))
review_list = ''.join(f'<article class="review-item"><span>{x["id"]}</span><div><h3>{escape(x["topic"])}</h3><p>{escape(x["finding"])}</p><small>{escape(x["location"])}</small></div></article>' for x in DATA['review_findings'])

